-- Reconstructed LC Pro Full Stack content part 2 (modules 4–7) from the verified LC Pro production state.
-- The remote migration version already exists; this file restores repository reproducibility.

with payload as (
  select * from jsonb_to_recordset($modules$[{"title":"Backend e APIs","position":4,"description":"HTTP, REST, contratos, validação, autenticação e regras de negócio no servidor."},{"title":"Banco de Dados e SQL","position":5,"description":"Modelagem relacional, consultas, integridade, índices, transações e migrações."},{"title":"Autenticação e Segurança","position":6,"description":"Sessões, autorização, proteção de segredos, OWASP, RLS e princípio do menor privilégio."},{"title":"Integração Full Stack","position":7,"description":"Frontend, API e banco trabalhando como um único produto com estados de loading, erro e sucesso."}]$modules$::jsonb)
  as x(position int,title text,description text)
), c as (select id from nexora.courses where slug='lc-pro-programador-full-stack')
update nexora.modules m
set title=p.title,description=p.description
from payload p,c
where m.course_id=c.id and m.position=p.position;

with payload as (
  select * from jsonb_to_recordset($lessons$[{"title":"Backend como fronteira de confiança","content":[{"body":"Um aplicativo pode ter site, mobile e integrações consumindo a mesma API. Se regras críticas ficam apenas no frontend, cada cliente passa a implementar uma versão diferente da verdade e qualquer requisição manual pode contorná-las.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"O backend é responsável por autenticação, autorização, validação de regra, coordenação de persistência e integração com segredos. O cliente pode antecipar validações para UX, mas o servidor deve ser capaz de receber uma requisição hostil e ainda preservar invariantes.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Considere toda entrada externa não confiável.","Autorize a operação, não apenas a rota.","Revalide regras críticas no servidor.","Nunca envie segredos de backend ao navegador."],"title":"Como pensar na prática"},{"body":"Para cancelar um pedido, a API verifica sessão, propriedade do pedido, status atual e regra de cancelamento antes de atualizar o banco. O botão escondido para outros usuários é apenas UX.","type":"example","title":"Exemplo aplicado"},{"body":"Confiar em `userId` enviado pelo cliente para decidir qual conta será alterada cria uma vulnerabilidade de autorização se o servidor não conferir identidade e propriedade.","type":"mistake","title":"Falha que parece pequena"},{"body":"Modele `DELETE /orders/:id`: liste autenticação, autorização, validação de estado e resultado esperado para pedido inexistente.","type":"guided_practice","title":"Prática orientada"},{"body":"Fronteiras de confiança bem definidas evitam BOLA/IDOR, dados inconsistentes e lógica duplicada entre clientes.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Cliente não é autoridade de segurança.","Servidor protege invariantes.","Autorização deve considerar recurso e ação.","Segredos permanecem em ambiente controlado."]}],"lab_type":"checkpoint","position":1,"objective":"Definir responsabilidades que precisam permanecer no servidor independentemente do cliente.","xp_reward":150,"difficulty":3,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["userId enviado no JSON","Identidade validada da sessão/token no servidor","Campo hidden da interface","Nome exibido no perfil"],"feedback":"Correto. A identidade deve vir de credencial validada pelo servidor.","question":"Qual dado deve ser usado como fonte principal de identidade numa operação autenticada?","feedback_incorrect":"Dados enviados pelo próprio cliente podem ser manipulados."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":4,"estimated_minutes":30},{"title":"Rotas, serviços e repositórios","content":[{"body":"Quando a rota conhece SQL, regra de desconto, envio de e-mail e formato de erro, qualquer alteração cruza várias responsabilidades. Testar uma regra exige subir servidor e banco mesmo quando isso não deveria ser necessário.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Uma separação pragmática usa handler/controller para traduzir HTTP, serviço para orquestrar regra de negócio e repositório/adaptador para persistência. Não é obrigatório criar uma classe para cada conceito; o objetivo é que mudanças em protocolo, regra e infraestrutura tenham fronteiras claras.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Handler interpreta request e monta response.","Serviço recebe tipos do domínio e executa caso de uso.","Repositório encapsula acesso a dados.","Integrações externas ficam em adaptadores explícitos."],"title":"Como pensar na prática"},{"body":"`createOrder(input, actor)` valida regra de negócio e chama `orders.save`. O handler decide se o resultado vira 201; o repositório decide como gravar no PostgreSQL.","type":"example","title":"Exemplo aplicado"},{"body":"Criar camadas que apenas repassam os mesmos argumentos sem separar responsabilidade adiciona arquivos, não arquitetura.","type":"mistake","title":"Falha que parece pequena"},{"body":"Separe o caso de uso “aprovar reembolso” em handler, serviço e persistência. Indique qual camada conhece status HTTP e qual conhece a regra de prazo.","type":"guided_practice","title":"Prática orientada"},{"body":"Fronteiras permitem testes mais baratos e substituição de infraestrutura. Também tornam revisão de segurança mais localizada.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["HTTP pertence à borda.","Regra de negócio precisa sobreviver à troca de framework.","Persistência deve ser encapsulada.","Camada só vale se separar uma razão de mudança."]}],"lab_type":"checkpoint","position":2,"objective":"Separar transporte HTTP, regras de negócio e persistência para reduzir acoplamento.","xp_reward":150,"difficulty":3,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["CSS","Serviço/caso de uso","Arquivo de rota apenas por ser HTTP","Componente React"],"feedback":"Correto. Prazo de reembolso é regra de negócio e deve ficar independente do transporte.","question":"Qual camada deveria decidir se um reembolso ainda está dentro do prazo permitido?","feedback_incorrect":"Separe regra de domínio de detalhes do protocolo."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":4,"estimated_minutes":32},{"title":"Validação e erros de API","content":[{"body":"APIs confiáveis precisam diferenciar entrada inválida, recurso ausente, conflito, falta de autenticação e falha inesperada. Se tudo vira 500, frontend e observabilidade perdem informação.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Validação tem camadas: formato e tipo na entrada, regra de negócio no caso de uso e invariantes persistentes no banco. O mapeamento HTTP traduz essas categorias sem vazar stack trace ou detalhes internos.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["400 para request malformada; 401 para ausência/invalidade de autenticação; 403 para ação proibida.","404 quando o recurso não deve ser encontrado; 409 para conflito de estado; 422 para validação semântica.","5xx representa falha inesperada do serviço.","Resposta de erro deve ter código estável e correlation id quando aplicável."],"title":"Como pensar na prática"},{"body":"Uma tentativa de cadastrar e-mail já existente pode gerar 409 `email_already_exists`; um campo fora do formato retorna 422 com erros por campo.","type":"example","title":"Exemplo aplicado"},{"body":"Retornar a mensagem bruta do banco, incluindo nome de tabela e SQL, ajuda depuração local mas expõe implementação e pode vazar dados em produção.","type":"mistake","title":"Falha que parece pequena"},{"body":"Crie uma tabela de erros para `POST /users`: JSON inválido, e-mail inválido, e-mail duplicado, usuário sem permissão e banco indisponível.","type":"guided_practice","title":"Prática orientada"},{"body":"Taxonomia de erros melhora produto, logs, alertas e suporte. Ela também evita que o frontend tome decisões baseadas em frases frágeis.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Nem todo erro é 500.","Validação existe em mais de uma camada.","Erro externo não deve expor internals.","Código estável é melhor que parsing de mensagem."]}],"lab_type":"checkpoint","position":3,"objective":"Validar formato e regras de negócio sem transformar toda falha em 500.","xp_reward":150,"difficulty":3,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":2,"options":["201","204","409","503"],"feedback":"Correto. 409 comunica conflito com o estado atual do recurso.","question":"Qual status representa melhor um conflito de unicidade conhecido, como e-mail já cadastrado?","feedback_incorrect":"Diferencie entrada inválida de conflito com um registro existente."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":4,"estimated_minutes":34},{"title":"REST, recursos e idempotência","content":[{"body":"Usuários dão duplo clique, proxies repetem chamadas e webhooks são reenviados. Uma API que assume “cada request chega uma vez” pode criar cobranças, pedidos ou registros duplicados.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"REST útil organiza operações em recursos e usa semântica HTTP consistente. Idempotência significa que repetir a mesma intenção não cria efeitos adicionais. GET, PUT e DELETE tendem a ser idempotentes por semântica; POST pode precisar de chave de idempotência quando cria efeitos financeiros ou únicos.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Nomeie recursos com substantivos estáveis.","Use métodos HTTP para intenção.","Defina o que acontece ao repetir a mesma requisição.","Para pagamentos/webhooks, grave identificador externo único."],"title":"Como pensar na prática"},{"body":"Um `POST /payments` recebe `Idempotency-Key`. O servidor associa a chave ao resultado; se a mesma chamada chegar novamente, devolve a operação existente em vez de cobrar de novo.","type":"example","title":"Exemplo aplicado"},{"body":"Gerar um UUID novo antes de verificar uma chave de idempotência não impede duplicação: o servidor já perdeu a capacidade de reconhecer a mesma intenção.","type":"mistake","title":"Falha que parece pequena"},{"body":"Projete a repetição de `POST /orders`, `PATCH /orders/1` e um webhook de pagamento. Indique onde precisa existir chave ou constraint.","type":"guided_practice","title":"Prática orientada"},{"body":"Idempotência é uma propriedade operacional. Ela reduz incidentes causados por redes instáveis e integrações que trabalham com entrega pelo menos uma vez.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Repetição é normal em sistemas distribuídos.","Recursos e métodos devem ter semântica previsível.","POST crítico pode precisar de idempotency key.","Constraint única complementa controle de duplicidade."]}],"lab_type":"checkpoint","position":4,"objective":"Projetar endpoints previsíveis e operações que toleram repetição quando necessário.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Trocar a cor do botão.","Chave de idempotência persistida no servidor.","Aumentar timeout indefinidamente.","Usar apenas GET para pagamentos."],"feedback":"Correto. A chave permite reconhecer e reutilizar o resultado da mesma intenção.","question":"Qual mecanismo ajuda a evitar duas cobranças quando a mesma intenção é reenviada?","feedback_incorrect":"A solução precisa funcionar mesmo se a repetição não vier da interface."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":4,"estimated_minutes":36},{"title":"Configuração, logs e observabilidade no backend","content":[{"body":"Um erro em produção que só gera `Something went wrong` é quase impossível de investigar. No outro extremo, logar request inteira pode registrar senha, token e dados pessoais.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Observabilidade começa com eventos estruturados: nome, request/correlation id, entidade técnica necessária, duração e resultado. Segredos e dados sensíveis precisam de redaction. Configuração vem de ambiente validado no startup.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Falhe cedo se variável obrigatória estiver ausente.","Use logs estruturados em vez de concatenação informal.","Propague correlation/request id.","Nunca registre token, senha ou payload sensível integral."],"title":"Como pensar na prática"},{"body":"Um evento pode registrar `{event:\"order_created\", order_id, actor_id, duration_ms}`. O ID permite correlacionar com outros serviços sem copiar todo o pedido para o log.","type":"example","title":"Exemplo aplicado"},{"body":"`console.log(req.headers.authorization)` pode parecer útil para depuração, mas transforma o sistema de logs em um repositório de credenciais.","type":"mistake","title":"Falha que parece pequena"},{"body":"Defina quais campos seriam registrados para um erro em integração de pagamento e quais seriam explicitamente removidos.","type":"guided_practice","title":"Prática orientada"},{"body":"Logs bons reduzem MTTR e permitem construir métricas; logs excessivos criam custo, ruído e risco de privacidade.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Configuração deve ser validada no início.","Log é dado operacional, não dump indiscriminado.","Correlation id conecta eventos.","Redaction faz parte de segurança."]}],"lab_type":"checkpoint","position":5,"objective":"Produzir logs estruturados e configuração segura sem expor dados sensíveis.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":2,"options":["request_id","duration_ms","token de autenticação completo","código estável do erro"],"feedback":"Correto. Credenciais completas não pertencem a logs.","question":"Qual informação NÃO deve ser registrada em logs de produção?","feedback_incorrect":"Log deve ajudar diagnóstico sem criar uma nova fonte de segredos."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":4,"estimated_minutes":38},{"title":"Webhooks e jobs assíncronos","content":[{"body":"Um provedor pode enviar o mesmo webhook várias vezes ou fora de ordem. Também pode haver timeout depois de o servidor processar, fazendo o provedor acreditar que precisa reenviar.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Webhook deve autenticar/verificar origem quando o provedor oferece assinatura, buscar o estado autoritativo quando necessário e persistir identificador do evento. O handler responde rápido; processamento pesado pode seguir em job. Retry exige operação idempotente.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Verifique assinatura ou consulte o provedor pela API.","Use event/payment id único.","Não confie somente no payload recebido.","Responda rápido e mova trabalho pesado para fila/job quando necessário."],"title":"Como pensar na prática"},{"body":"Um webhook de pagamento recebe `payment_id`, busca o pagamento no provedor, compara valor/referência com o pedido local e só então muda o estado. Repetições encontram o mesmo `payment_id` já processado.","type":"example","title":"Exemplo aplicado"},{"body":"Conceder acesso apenas porque alguém fez POST no endpoint público do webhook permite forjar eventos se não houver verificação externa.","type":"mistake","title":"Falha que parece pequena"},{"body":"Desenhe o fluxo seguro de “pagamento aprovado → liberar curso”, incluindo reenvio do mesmo evento e reembolso posterior.","type":"guided_practice","title":"Prática orientada"},{"body":"Webhooks são integração distribuída, não callbacks confiáveis. Pensar em duplicidade e ordem desde o início evita bugs financeiros.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Webhook público precisa de verificação.","Estado crítico deve ser confirmado.","Eventos são potencialmente repetidos.","Retry seguro exige idempotência."]}],"lab_type":"checkpoint","position":6,"objective":"Processar eventos externos com verificação, idempotência e possibilidade de retry.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Confiar no JSON recebido sem verificação.","Consultar/validar o evento com o provedor e comparar referência/valor.","Liberar acesso antes de ler o pedido.","Desabilitar logs."],"feedback":"Correto. O servidor deve confirmar o evento e relacioná-lo ao pedido esperado.","question":"Qual é a melhor defesa quando um webhook informa pagamento aprovado?","feedback_incorrect":"Um endpoint público não deve transformar qualquer payload em autorização financeira."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":4,"estimated_minutes":30},{"title":"Modelagem relacional orientada ao domínio","content":[{"body":"Modelos ruins aparecem primeiro como código cheio de exceções e depois como relatórios inconsistentes. Se endereço, cliente e pedido estão misturados sem regra, cada atualização pode deixar versões conflitantes do mesmo fato.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Modelagem relacional separa entidades, relacionamentos e atributos conforme identidade e ciclo de vida. Chaves primárias identificam linhas; chaves estrangeiras representam relações; tabelas de junção modelam muitos-para-muitos.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Defina identidade de cada entidade.","Escolha onde cada fato deve existir uma única vez.","Modele cardinalidade explicitamente.","Use tabela de junção quando ambos os lados podem ter muitos registros."],"title":"Como pensar na prática"},{"type":"example","title":"Exemplo técnico","segments":[{"body":"Pedidos e produtos formam muitos-para-muitos. `order_items` guarda `order_id`, `product_id`, quantidade e preço praticado, porque esses atributos pertencem à relação naquele momento.","kind":"text"},{"body":"create table project_members (\n  project_id uuid references projects(id),\n  user_id uuid references users(id),\n  role text not null,\n  primary key (project_id, user_id)\n);","kind":"code","language":"sql"}]},{"body":"Guardar `product_ids` como string separada por vírgulas simplifica um insert, mas destrói integridade referencial e torna consultas e constraints difíceis.","type":"mistake","title":"Falha que parece pequena"},{"body":"Modele usuários, projetos e membros de projeto, permitindo papéis diferentes por projeto.","type":"guided_practice","title":"Prática orientada"},{"body":"Um schema bem modelado reduz regra duplicada no backend e torna consultas analíticas mais confiáveis.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Entidade tem identidade e ciclo de vida.","Fato deve ter fonte de verdade.","FK expressa relacionamento.","Muitos-para-muitos pede entidade de relação."]}],"lab_type":"checkpoint","position":1,"objective":"Transformar entidades e relacionamentos em tabelas sem duplicar fatos desnecessariamente.","xp_reward":150,"difficulty":3,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Uma coluna projects em users com texto CSV.","Tabela project_members com user_id, project_id e role.","Uma tabela diferente para cada usuário.","Duplicar dados do usuário em projects."],"feedback":"Correto. A tabela de relação representa participação e seus atributos.","question":"Como modelar muitos usuários participando de muitos projetos com um papel por participação?","feedback_incorrect":"O relacionamento possui dados próprios e precisa de integridade referencial."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":5,"estimated_minutes":32},{"title":"Constraints e integridade no banco","content":[{"body":"Se uma regra só existe no frontend e no backend, scripts, migrações ou novas integrações podem gravar dados inválidos. O banco é a última fronteira antes do estado persistente.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Constraints transformam invariantes simples em propriedades do schema. `NOT NULL` exige presença, `UNIQUE` evita duplicidade, `CHECK` limita valores e FK impede referência inexistente. A aplicação continua validando para oferecer mensagens melhores.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Use constraint para regra estrutural persistente.","Evite enumeração livre quando valores são fechados.","Dê nomes previsíveis às constraints importantes.","Planeje ON DELETE conforme ciclo de vida real."],"title":"Como pensar na prática"},{"body":"Uma tabela de pedidos pode exigir `amount_cents >= 0`, status em conjunto permitido e `user_id` referenciando usuário existente.","type":"example","title":"Exemplo aplicado"},{"body":"Confiar em `if (amount >= 0)` no código sem CHECK deixa o banco vulnerável a outras rotas de escrita.","type":"mistake","title":"Falha que parece pequena"},{"body":"Escolha constraints para uma tabela `subscriptions` com usuário, plano, status, início e expiração opcional.","type":"guided_practice","title":"Prática orientada"},{"body":"Integridade no banco reduz classes inteiras de bugs e facilita correções porque estados inválidos simplesmente não entram.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Aplicação valida; banco garante invariantes estruturais.","UNIQUE e FK evitam inconsistências comuns.","CHECK documenta regras simples.","ON DELETE é decisão de domínio."]}],"lab_type":"checkpoint","position":2,"objective":"Usar tipos, NOT NULL, UNIQUE, CHECK e foreign keys para impedir estados impossíveis.","xp_reward":150,"difficulty":3,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["ORDER BY","UNIQUE constraint","LEFT JOIN","VIEW"],"feedback":"Correto. A constraint garante a regra independentemente do caminho de escrita.","question":"Qual mecanismo impede duas linhas com o mesmo e-mail quando essa unicidade é obrigatória?","feedback_incorrect":"A regra deve ser protegida no estado persistente, não só na interface."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":5,"estimated_minutes":34},{"title":"JOIN, agregação e consultas legíveis","content":[{"body":"Dashboards frequentemente mostram números diferentes porque cada tela reimplementa a relação entre pedidos, itens e clientes. SQL precisa expressar claramente qual linha representa cada entidade antes de agregar.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"JOIN combina relações com base em chaves. GROUP BY muda a granularidade do resultado. Antes de usar COUNT ou SUM, defina qual unidade cada linha representa para evitar multiplicações acidentais.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Comece pela granularidade esperada da saída.","Use JOIN com condição explícita.","Agrupe somente após entender a multiplicação de linhas.","Use aliases e CTEs quando melhoram legibilidade."],"title":"Como pensar na prática"},{"type":"example","title":"Exemplo técnico","segments":[{"body":"Para receita por cliente, primeiro relacione pedidos aprovados a clientes, depois agrupe por cliente. Se juntar itens também, cada pedido pode aparecer várias vezes e exigir cálculo apropriado.","kind":"text"},{"body":"select c.id, c.name, count(distinct o.id) as orders\nfrom customers c\nleft join orders o on o.customer_id = c.id\ngroup by c.id, c.name;","kind":"code","language":"sql"}]},{"body":"Usar `count(*)` depois de juntar pedidos e itens pode contar itens, não pedidos. O SQL está correto sintaticamente e errado semanticamente.","type":"mistake","title":"Falha que parece pequena"},{"body":"Escreva duas consultas conceituais: número de pedidos por cliente e quantidade de itens vendidos por produto. Defina a granularidade antes do SQL.","type":"guided_practice","title":"Prática orientada"},{"body":"Consultas legíveis facilitam revisão de métricas e evitam decisões de negócio baseadas em números inflados.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["JOIN altera conjunto de linhas.","Agregação depende da granularidade.","COUNT pode medir entidade errada após join.","CTE pode tornar etapas explícitas."]}],"lab_type":"checkpoint","position":3,"objective":"Combinar tabelas e calcular métricas sem esconder a lógica da consulta.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Sempre clientes.","As linhas resultantes da junção, frequentemente itens.","Sempre pedidos distintos.","Apenas valores não nulos da primeira tabela."],"feedback":"Correto. A granularidade após o JOIN determina o significado da contagem.","question":"Depois de juntar pedidos com itens, `count(*)` tende a contar o quê?","feedback_incorrect":"Antes de agregar, descubra o que cada linha do resultado representa."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":5,"estimated_minutes":36},{"title":"Transações e concorrência","content":[{"body":"Duas requisições podem ler o mesmo estoque e tentar vender a última unidade. Em execução sequencial tudo funciona; sob concorrência, ambas podem aprovar.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Transação agrupa mudanças que precisam confirmar ou falhar juntas. Concorrência exige pensar em isolamento, locks, constraints e operações atômicas. O objetivo não é bloquear tudo, mas proteger invariantes específicos.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Use transação para mudanças dependentes.","Prefira UPDATE condicional/atômico quando possível.","Constraints continuam úteis sob concorrência.","Planeje retry para conflitos transitórios."],"title":"Como pensar na prática"},{"body":"Em vez de ler estoque 1 e depois atualizar, uma operação pode executar `UPDATE inventory SET qty=qty-1 WHERE id=? AND qty>0` e verificar quantas linhas foram afetadas.","type":"example","title":"Exemplo aplicado"},{"body":"Uma transação não corrige automaticamente lógica de concorrência se duas transações ainda podem tomar decisões sobre dados antigos.","type":"mistake","title":"Falha que parece pequena"},{"body":"Modele transferência de saldo entre duas contas. Liste o que precisa acontecer na mesma transação e qual invariante não pode ser quebrada.","type":"guided_practice","title":"Prática orientada"},{"body":"Incidentes de concorrência são raros em testes locais e comuns em operações valiosas. Proteger invariantes no banco é mais robusto que confiar em timing.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Transação garante atomicidade de um conjunto de mudanças.","Concorrência exige operação pensada para disputa.","UPDATE condicional reduz janela de corrida.","Retry pode fazer parte do desenho."]}],"lab_type":"checkpoint","position":4,"objective":"Preservar consistência quando uma operação exige múltiplas escritas ou ocorre simultaneamente.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Ler quantidade no frontend e confiar nela.","UPDATE condicional que só decrementa se qty > 0.","Adicionar sleep antes do update.","Fazer duas leituras iguais."],"feedback":"Correto. A condição é aplicada atomicamente na escrita.","question":"Qual abordagem reduz melhor a corrida ao consumir a última unidade de estoque?","feedback_incorrect":"A decisão precisa ocorrer onde o estado é atualizado, não num snapshot antigo."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":5,"estimated_minutes":38},{"title":"Índices e planos de consulta","content":[{"body":"Adicionar índice em toda coluna aumenta escrita e armazenamento sem garantir consultas melhores. Por outro lado, filtrar milhões de linhas sem índice adequado pode dominar a latência da API.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Índice acelera certos caminhos de busca ao custo de manutenção. A escolha deve considerar filtros, joins, ordenação, cardinalidade e frequência. `EXPLAIN`/plano mostra o que o banco decidiu fazer.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Indexe colunas usadas em filtros/join relevantes.","Índice composto respeita ordem e padrão de consulta.","Evite otimizar consulta que não é gargalo.","Meça plano e tempo antes/depois."],"title":"Como pensar na prática"},{"body":"Uma consulta frequente `WHERE organization_id=? AND status='open' ORDER BY created_at DESC` pode se beneficiar de índice alinhado a organização, status e ordenação, dependendo da distribuição.","type":"example","title":"Exemplo aplicado"},{"body":"Criar índice isolado para cada coluna não equivale automaticamente a um índice composto útil para a consulta real.","type":"mistake","title":"Falha que parece pequena"},{"body":"Escolha um endpoint lento e descreva quais dados você coletaria antes de criar um índice.","type":"guided_practice","title":"Prática orientada"},{"body":"Performance de banco é uma disciplina de evidência. Bons índices nascem de workload, não de superstição.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Índice tem custo de escrita.","Padrão de acesso define índice útil.","Plano de execução fornece evidência.","Otimização precisa ser medida."]}],"lab_type":"checkpoint","position":5,"objective":"Otimizar consultas a partir de padrão real de acesso e evidência do plano.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Adicionar índices em todas as colunas.","Examinar a consulta e seu plano de execução.","Remover foreign keys.","Trocar todos os tipos para text."],"feedback":"Correto. O plano ajuda a identificar onde o banco está gastando trabalho.","question":"Qual é o melhor primeiro passo antes de adicionar um índice para uma consulta lenta?","feedback_incorrect":"Otimize a partir de evidência do caminho executado."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":5,"estimated_minutes":30},{"title":"Migrações e queries parametrizadas","content":[{"body":"Banco em produção muda enquanto dados reais existem. Um `ALTER` improvisado ou SQL montado por concatenação pode transformar uma pequena feature em indisponibilidade ou vulnerabilidade.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Migração é uma mudança versionada e reproduzível do schema. Queries com valores externos usam parâmetros/prepared statements; nomes de tabela/coluna dinâmicos exigem lista permitida, não parâmetros de valor.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Versione migrações junto ao código.","Planeje compatibilidade durante deploy gradual.","Faça mudanças destrutivas em etapas.","Parametrize todo valor vindo de usuário ou integração."],"title":"Como pensar na prática"},{"type":"example","title":"Exemplo técnico","segments":[{"body":"Em vez de `WHERE email='${email}'`, use placeholder do driver e envie o valor separadamente. O banco interpreta o valor como dado, não como parte da sintaxe.","kind":"text"},{"body":"const result = await db.query(\n  \"select id, name from users where email = $1\",\n  [email]\n);","kind":"code","language":"javascript"}]},{"body":"Escapar aspas manualmente não é substituto confiável para parametrização. Também é fácil esquecer um único caminho.","type":"mistake","title":"Falha que parece pequena"},{"body":"Planeje uma migração de coluna `full_name` obrigatória num banco que já possui usuários sem valor. Divida em etapas compatíveis.","type":"guided_practice","title":"Prática orientada"},{"body":"Migrações reversíveis ou pelo menos recuperáveis, backups e deploy coordenado reduzem risco de mudanças de schema.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Migração é código operacional versionado.","Mudança destrutiva pede etapas.","Valores externos são parâmetros.","SQL dinâmico de identificador deve usar allowlist."]}],"lab_type":"checkpoint","position":6,"objective":"Alterar schema com segurança e impedir injeção SQL em dados externos.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Concatenar strings e remover aspas.","Prepared statement/query parametrizada.","Codificar tudo em base64.","Usar comentários SQL."],"feedback":"Correto. Valores ficam separados da estrutura da consulta.","question":"Qual padrão protege valores externos contra injeção SQL?","feedback_incorrect":"A defesa deve vir da interface do driver, não de filtros manuais."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":5,"estimated_minutes":32},{"title":"Autenticação, sessão e identidade","content":[{"body":"Login bem-sucedido responde apenas “quem é”. Ele não diz se a pessoa pode editar qualquer projeto, ver admin ou acessar dados de outro usuário.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Autenticação estabelece identidade; sessão mantém essa identidade entre requisições; autorização decide ações. Tokens e cookies são mecanismos de transporte/estado, não a política em si.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Valide credencial numa fronteira confiável.","Sessão deve expirar e poder ser revogada conforme risco.","Autorização usa identidade validada.","Não derive permissão de metadata editável pelo usuário."],"title":"Como pensar na prática"},{"body":"Uma sessão identifica `user_id=123`. Ao abrir `/projects/9`, a autorização ainda verifica se 123 participa do projeto 9 com papel suficiente.","type":"example","title":"Exemplo aplicado"},{"body":"Checar apenas `isLoggedIn` em endpoint administrativo transforma qualquer conta autenticada em administradora.","type":"mistake","title":"Falha que parece pequena"},{"body":"Liste as três perguntas para `PATCH /projects/9`: quem é? ainda está autenticado? pode editar este projeto específico?","type":"guided_practice","title":"Prática orientada"},{"body":"Separar autenticação e autorização evita BOLA/IDOR e torna políticas auditáveis.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Login não concede acesso universal.","Sessão representa identidade ao longo do tempo.","Autorização é contextual.","Permissão precisa ser derivada de dados confiáveis."]}],"lab_type":"checkpoint","position":1,"objective":"Distinguir prova de identidade, sessão e autorização para não misturar controles.","xp_reward":150,"difficulty":3,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Somente se a tela tem botão Editar.","Se a identidade possui autorização para aquele recurso e ação.","A resolução da tela.","A linguagem do navegador."],"feedback":"Correto. Autenticação e autorização resolvem perguntas diferentes.","question":"Após autenticar um usuário, o que ainda precisa ser verificado antes de editar um recurso?","feedback_incorrect":"Estar logado não define automaticamente quais recursos podem ser modificados."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":6,"estimated_minutes":34},{"title":"Senhas, cookies e tokens com segurança","content":[{"body":"Salvar senha em texto puro transforma qualquer vazamento de banco em comprometimento imediato de contas. Guardar token em local inadequado pode ampliar impacto de XSS.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Senhas devem ser armazenadas com função de hashing de senha resistente e salt, nunca criptografia reversível por conveniência. Cookies de sessão podem usar HttpOnly, Secure e SameSite conforme arquitetura. Tokens precisam de expiração e escopo.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Use função própria para hashing de senha.","Nunca logue senha ou token completo.","Proteja cookie com atributos adequados.","Rotacione/revogue credenciais quando comprometidas."],"title":"Como pensar na prática"},{"body":"O servidor guarda apenas hash de senha. No login, compara a senha fornecida usando a função de verificação. A aplicação nunca precisa recuperar a senha original.","type":"example","title":"Exemplo aplicado"},{"body":"Usar SHA-256 puro diretamente para senhas é rápido demais e não substitui algoritmos desenhados para resistência a brute force.","type":"mistake","title":"Falha que parece pequena"},{"body":"Descreva o fluxo de troca de senha após suspeita de vazamento: sessão, credencial antiga, novos tokens e revogação.","type":"guided_practice","title":"Prática orientada"},{"body":"Segurança de sessão deve considerar roubo, expiração e recuperação, não apenas o formulário de login.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Senha não deve ser recuperável do banco.","Hash de senha é diferente de hash genérico.","Cookies/tokens precisam de proteção e expiração.","Incidente exige revogação, não só alterar interface."]}],"lab_type":"checkpoint","position":2,"objective":"Aplicar práticas seguras para armazenamento de senha e transporte de sessão.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Texto puro para facilitar suporte.","Hash produzido por função apropriada para senhas.","Base64 reversível.","Dentro do log de autenticação."],"feedback":"Correto. O sistema verifica o hash sem precisar recuperar a senha original.","question":"Como uma senha deve ser armazenada no banco?","feedback_incorrect":"Procure um mecanismo resistente a brute force e não reversível."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":6,"estimated_minutes":36},{"title":"Autorização por propriedade e papéis","content":[{"body":"Uma API pode proteger `/admin` e ainda permitir que `GET /orders/123` entregue o pedido de outra pessoa. Esse é um erro de autorização no objeto, não de autenticação.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Autorização precisa combinar identidade, recurso e ação. Papéis tratam capacidades amplas; propriedade ou membership trata escopo de dados. Consultas podem incorporar o usuário para que registros fora do escopo nem sejam encontrados.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Filtre recurso pelo escopo autorizado.","Não aceite `owner_id` do cliente como decisão final.","Diferencie admin de dono/membro.","Retorne mínimo necessário para o papel."],"title":"Como pensar na prática"},{"type":"example","title":"Exemplo técnico","segments":[{"body":"Em vez de buscar pedido por `id` e depois esquecer a checagem, consulte `WHERE id=$1 AND user_id=$2` para caminhos de dono, mantendo fluxo administrativo separado.","kind":"text"},{"body":"create policy \"read own rows\"\non app.documents for select\nto authenticated\nusing ((select auth.uid()) = user_id);","kind":"code","language":"sql"}]},{"body":"Uma policy `TO authenticated USING (true)` autentica, mas não autoriza linhas. Qualquer usuário autenticado pode passar.","type":"mistake","title":"Falha que parece pequena"},{"body":"Modele regras para documento privado, documento compartilhado e administrador. Escreva quais consultas/policies cada caso precisa.","type":"guided_practice","title":"Prática orientada"},{"body":"Controle de acesso eficaz é aplicado perto dos dados e repetido nas fronteiras relevantes.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Autorização horizontal protege dados entre usuários.","Papel não substitui escopo do recurso.","Filtro por usuário reduz chance de esquecimento.","Acesso mínimo deve ser padrão."]}],"lab_type":"checkpoint","position":3,"objective":"Prevenir acesso horizontal e vertical verificando recurso, usuário e ação.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["USING (true)","USING (auth.uid() = user_id)","USING (status IS NOT NULL)","Sem RLS"],"feedback":"Correto. A policy vincula a linha à identidade autenticada.","question":"Qual policy representa melhor acesso do próprio usuário a linhas com `user_id`?","feedback_incorrect":"Autenticação sozinha não limita quais linhas uma conta pode ler."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":6,"estimated_minutes":38},{"title":"Injeção, XSS e saída segura","content":[{"body":"Os mesmos caracteres podem ser inofensivos como texto e perigosos quando viram SQL, HTML ou JavaScript. Segurança não é “remover símbolos estranhos”; é impedir que dado seja interpretado como instrução.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"SQL usa parâmetros para valores. Interface deve inserir texto como texto, não HTML arbitrário. Quando HTML é realmente necessário, exige sanitização apropriada ao contexto e política explícita.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["SQL: parâmetros/prepared statements.","DOM: `textContent` para texto não confiável.","HTML rico: sanitize com biblioteca adequada e allowlist.","Nunca monte script com entrada do usuário."],"title":"Como pensar na prática"},{"type":"example","title":"Exemplo técnico","segments":[{"body":"Para mostrar comentário, `element.textContent = comment.body` preserva o conteúdo como texto. `innerHTML = comment.body` interpreta marcação e pode criar XSS.","kind":"text"},{"body":"messageEl.textContent = userComment;","kind":"code","language":"javascript"}]},{"body":"Bloquear apenas `<script>` não resolve XSS: existem atributos, URLs e outros contextos executáveis.","type":"mistake","title":"Falha que parece pequena"},{"body":"Classifique quatro entradas — nome, filtro SQL, HTML de editor rico e URL externa — e escolha tratamento seguro para cada contexto.","type":"guided_practice","title":"Prática orientada"},{"body":"Segurança de entrada/saída depende do contexto. Uma única função “sanitizeEverything” raramente é correta para todos.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Dado não deve virar sintaxe.","Parâmetro protege SQL.","textContent evita interpretação HTML.","Sanitização depende do contexto."]}],"lab_type":"checkpoint","position":4,"objective":"Reduzir risco tratando entrada como dado e aplicando escaping no contexto correto.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":2,"options":["innerHTML","outerHTML","textContent","document.write"],"feedback":"Correto. `textContent` não interpreta a entrada como marcação HTML.","question":"Qual propriedade é preferível para inserir comentário não confiável como texto no DOM?","feedback_incorrect":"A defesa deve impedir que texto fornecido pelo usuário vire código/marcação executável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":6,"estimated_minutes":30},{"title":"CORS, CSRF e gestão de segredos","content":[{"body":"CORS é frequentemente tratado como “segurança da API” genérica, mas ele controla quais origens podem ler respostas no navegador. Não substitui autenticação. Já CSRF explora credenciais enviadas automaticamente, como cookies, para disparar ação indesejada.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"CORS deve ser restrito às origens necessárias. APIs baseadas em cookie precisam considerar SameSite e token anti-CSRF conforme fluxo. Segredos de servidor nunca devem entrar em bundle público; chaves públicas precisam ser tratadas de acordo com o modelo do provedor.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["CORS não impede chamadas fora do navegador.","Cookie de sessão pede estratégia contra CSRF.","Variável com prefixo público no frontend é pública.","Rotacione segredo exposto; apagar do Git não basta."],"title":"Como pensar na prática"},{"body":"Uma API usada por `app.exemplo.com` permite essa origem e métodos necessários. A chave privada do gateway fica no backend; o navegador recebe apenas dados resultantes.","type":"example","title":"Exemplo aplicado"},{"body":"Configurar `Access-Control-Allow-Origin: *` e assumir que a API ficou protegida faz o oposto: amplia leitura em browser quando credenciais/políticas permitem.","type":"mistake","title":"Falha que parece pequena"},{"body":"Analise um projeto que colocou `SERVICE_ROLE_KEY` no frontend. Liste ações imediatas: revogação/rotação, remoção do bundle e revisão de impacto.","type":"guided_practice","title":"Prática orientada"},{"body":"Gestão de segredos faz parte do ciclo de incidentes e deploy. Repositório público apagado ainda pode ter clones e histórico.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["CORS controla contexto de navegador, não identidade.","CSRF depende do modelo de credencial.","Segredo de servidor não vai ao cliente.","Credencial exposta deve ser rotacionada."]}],"lab_type":"checkpoint","position":5,"objective":"Entender controles que atuam em problemas diferentes e manter segredos fora do cliente.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Só apagar o arquivo no próximo commit.","Rotacionar/revogar a credencial e remover o uso indevido.","Renomear a variável.","Esconder o repositório e manter a mesma chave."],"feedback":"Correto. Uma credencial exposta deve ser considerada comprometida.","question":"O que deve acontecer quando um segredo de backend foi commitado publicamente?","feedback_incorrect":"Remover texto do branch atual não invalida cópias já obtidas."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":6,"estimated_minutes":32},{"title":"RLS, rate limiting e threat modeling","content":[{"body":"Uma API pode estar correta para um usuário legítimo e ainda ser abusada por milhares de requisições. Também pode esquecer uma checagem em nova rota. Defesa em profundidade reduz o impacto de falhas individuais.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"RLS aplica política no banco por linha; rate limiting controla frequência/abuso; threat modeling identifica ativos, atores, superfícies e controles antes do incidente. Nenhum substitui os outros.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Use RLS para isolamento quando o banco é exposto por API.","Rate limit por identidade/ação conforme risco.","Proteja operações privilegiadas com checagem interna, não só nome de função.","Revise fluxos de pagamento, upload e admin como superfícies especiais."],"title":"Como pensar na prática"},{"body":"Uma tabela de documentos usa RLS por `user_id`; endpoint de exportação ainda aplica autorização; login e reset têm rate limit; a equipe documenta como abuso e exfiltração seriam detectados.","type":"example","title":"Exemplo aplicado"},{"body":"`SECURITY DEFINER` sem checagem de usuário pode ignorar RLS e virar um endpoint privilegiado acessível por qualquer conta com EXECUTE.","type":"mistake","title":"Falha que parece pequena"},{"body":"Faça threat model de uma função “emitir certificado”: ativo, quem deveria chamar, entradas, abuso possível e controles.","type":"guided_practice","title":"Prática orientada"},{"body":"Threat modeling não prevê todo ataque; ele força a equipe a discutir falhas antes de elas virarem arquitetura permanente.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Defesa em profundidade combina controles.","RLS protege linhas, não frequência.","Rate limit reduz abuso, não corrige autorização.","Código privilegiado precisa validar caller explicitamente."]}],"lab_type":"checkpoint","position":6,"objective":"Combinar controles de dados, abuso e análise de ameaça em vez de depender de uma única barreira.","xp_reward":150,"difficulty":5,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Nenhum, porque RLS sempre se aplica.","Ela pode executar com privilégios elevados e contornar RLS.","Apenas deixa a query mais lenta.","Somente altera CSS."],"feedback":"Correto. SECURITY DEFINER executa com privilégios do dono e exige desenho cuidadoso.","question":"Qual risco existe em uma função `SECURITY DEFINER` exposta sem checagem interna de autorização?","feedback_incorrect":"Função privilegiada pode transformar EXECUTE em uma rota de escalada."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":6,"estimated_minutes":34},{"title":"Contrato compartilhado entre frontend e backend","content":[{"body":"Uma API muda `dueDate` para `due_at` e o frontend só descobre em produção. O problema não é JSON: é ausência de contrato validado entre consumidores.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Contrato pode ser documentado por schema e tipos derivados/compartilhados quando isso não acopla indevidamente os serviços. O backend valida runtime; TypeScript valida compile time no cliente. Compatibilidade precisa ser pensada durante evolução.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Schema de runtime continua necessário para dados externos.","Tipos de frontend não validam rede sozinhos.","Mudança aditiva tende a ser mais compatível que renomear/remover.","Versione quando quebra consumidores independentes."],"title":"Como pensar na prática"},{"body":"Uma resposta de tarefa inclui `id`, `title`, `status`. Adicionar `priority` opcional é mais fácil de absorver do que substituir `status` por formato incompatível sem transição.","type":"example","title":"Exemplo aplicado"},{"body":"Importar tipos internos do backend diretamente para o frontend pode vazar campos privados e criar dependência de implementação.","type":"mistake","title":"Falha que parece pequena"},{"body":"Planeje a evolução de `User` para adicionar avatar e retirar um campo antigo. Descreva uma fase compatível.","type":"guided_practice","title":"Prática orientada"},{"body":"Contrato testável permite integração contínua e reduz bugs de deploy parcial.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Rede precisa de validação runtime.","Tipos ajudam, mas não autenticam dados.","Evolução compatível reduz deploy coordenado.","Contrato público deve conter apenas dados públicos."]}],"lab_type":"checkpoint","position":1,"objective":"Reduzir divergência de dados usando contratos versionados e validação nas duas pontas.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Porque TypeScript não funciona com React.","Porque tipos são apagados em runtime e a rede ainda pode trazer dados diferentes.","Porque JSON não tem strings.","Porque HTTP só envia bytes tipados."],"feedback":"Correto. O dado externo precisa ser validado em runtime.","question":"Por que TypeScript no frontend não substitui validação do JSON recebido da API?","feedback_incorrect":"O compilador não controla o que um servidor ou cache realmente envia."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":7,"estimated_minutes":36},{"title":"Autenticação ponta a ponta","content":[{"body":"Uma SPA pode mostrar página privada enquanto a sessão já expirou, ou entrar em loop de refresh quando duas requisições recebem 401 ao mesmo tempo.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Fluxo de autenticação precisa de estado explícito: desconhecido durante bootstrap, autenticado, anônimo e expirado. O cliente encaminha credencial; o servidor valida. 401 normalmente pede reautenticação/refresh; 403 indica identidade conhecida sem permissão.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Não renderize conteúdo privado antes de resolver sessão.","Centralize refresh para evitar múltiplas renovações concorrentes.","Diferencie 401 e 403.","Servidor continua protegendo rota mesmo que frontend tenha guard."],"title":"Como pensar na prática"},{"body":"Durante bootstrap, a aplicação mostra estado neutro, verifica sessão e só então escolhe dashboard ou login. Uma chamada 403 mantém sessão e exibe falta de permissão.","type":"example","title":"Exemplo aplicado"},{"body":"Tratar todo 403 como logout confunde autorização com autenticação e pode expulsar usuários válidos de áreas permitidas.","type":"mistake","title":"Falha que parece pequena"},{"body":"Desenhe máquina de estados para sessão: loading, authenticated, anonymous, refreshing e failed.","type":"guided_practice","title":"Prática orientada"},{"body":"Autenticação bem integrada evita flashes de dados, loops e experiências contraditórias entre frontend e API.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Bootstrap de sessão é assíncrono.","401 e 403 têm significados diferentes.","Frontend protege experiência; backend protege recurso.","Refresh concorrente precisa de coordenação."]}],"lab_type":"checkpoint","position":2,"objective":"Integrar sessão, renovação, estados 401/403 e proteção de rotas sem depender apenas de redirects.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["O servidor não existe.","A identidade é conhecida, mas a ação não é permitida.","O JSON está sempre inválido.","A sessão foi necessariamente apagada."],"feedback":"Correto. 403 representa falta de autorização para a ação/recurso.","question":"O que um 403 normalmente comunica?","feedback_incorrect":"Não confunda ausência de credencial com permissão insuficiente."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":7,"estimated_minutes":38},{"title":"Cache, invalidação e consistência de UI","content":[{"body":"Cache deixa a interface rápida, mas também pode exibir informação antiga. Após editar uma tarefa, lista e detalhe podem divergir se apenas um lugar for atualizado.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Cache deve ter chave estável e política de frescor. Após mutação, a aplicação pode atualizar otimisticamente, substituir pelo resultado do servidor ou invalidar consultas relacionadas. O servidor continua como fonte autoritativa.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Chave de cache deve incluir parâmetros que mudam resultado.","Mutação precisa declarar quais leituras ficaram obsoletas.","Atualização otimista exige rollback em falha.","Não cache dado sensível além do necessário."],"title":"Como pensar na prática"},{"body":"Após `PATCH /tasks/7`, o cliente substitui o item 7 pelo payload retornado e invalida contadores que dependem do status da tarefa.","type":"example","title":"Exemplo aplicado"},{"body":"Atualizar apenas o componente clicado sem atualizar o cache global cria uma interface correta localmente e errada ao navegar.","type":"mistake","title":"Falha que parece pequena"},{"body":"Mapeie as leituras afetadas por “marcar pedido como pago”: detalhe, lista, dashboard e saldo.","type":"guided_practice","title":"Prática orientada"},{"body":"Consistência de cache é parte da modelagem de dados do frontend, não um detalhe da biblioteca escolhida.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Cache tem identidade e validade.","Mutação cria invalidações.","Otimismo precisa de rollback.","Servidor é fonte final de verdade."]}],"lab_type":"checkpoint","position":3,"objective":"Decidir quando reutilizar dados e como invalidá-los após mutações.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Nada, porque cache nunca expira.","Ser atualizadas ou invalidadas conforme dependência.","Ser convertidas em localStorage permanente.","Ter seus erros ignorados."],"feedback":"Correto. Leituras dependentes precisam refletir a mudança ou serem recarregadas.","question":"Após uma mutação que altera o status de uma tarefa, o que deve acontecer com leituras derivadas desse status?","feedback_incorrect":"Cache sem invalidação produz estados contraditórios."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":7,"estimated_minutes":30},{"title":"Uploads e integrações externas","content":[{"body":"Upload conecta navegador, API, storage, banco e eventualmente processamento. Se o banco registra arquivo antes do upload completar, pode sobrar referência quebrada; se a storage key é previsível, pode haver acesso indevido.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Fluxo precisa definir tamanho/tipo permitido, caminho não adivinhável ou protegido, política de acesso e ordem das operações. URL assinada pode conceder acesso temporário sem tornar o bucket público.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Valide tamanho e tipo no servidor/storage.","Associe arquivo à identidade e recurso autorizados.","Use URL assinada quando acesso deve expirar.","Trate órfãos e falhas entre storage e banco."],"title":"Como pensar na prática"},{"body":"Para anexo privado, API verifica membership, gera caminho com IDs internos, autoriza upload e grava metadata apenas após confirmação. Download exige nova autorização ou URL assinada curta.","type":"example","title":"Exemplo aplicado"},{"body":"Confiar apenas na extensão `.pdf` enviada pelo navegador não valida conteúdo nem impede upload enorme.","type":"mistake","title":"Falha que parece pequena"},{"body":"Projete upload de comprovante privado e liste estados de falha: rede, tipo, storage, gravação de metadata e autorização.","type":"guided_practice","title":"Prática orientada"},{"body":"Uploads viram superfície de custo e segurança. Limites, lifecycle e auditoria precisam existir antes de escalar.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Arquivo é dado não confiável.","Storage precisa de política de acesso.","URL pública não serve para todo caso.","Falha parcial precisa de limpeza/recuperação."]}],"lab_type":"checkpoint","position":4,"objective":"Projetar upload com validação, armazenamento, autorização e falhas parciais.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Bucket público permanente.","URL assinada com expiração após autorização.","Nome de arquivo secreto como única proteção.","Enviar service role ao navegador."],"feedback":"Correto. A URL assinada concede acesso limitado após checagem de autorização.","question":"Qual abordagem é adequada para download temporário de arquivo privado?","feedback_incorrect":"Segredo ou privilégio do servidor não deve ser entregue ao cliente."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":7,"estimated_minutes":32},{"title":"Webhooks, realtime e reconciliação","content":[{"body":"Interfaces em tempo real parecem simples até conexão cair ou evento duplicar. Um painel pode perder atualização e permanecer errado se não houver forma de reconciliar com o estado persistente.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Eventos devem ser tratados como notificações de mudança, não necessariamente como única fonte de verdade. Cliente aplica evento quando válido e periodicamente/reconectando consulta estado autoritativo. Webhooks externos seguem a mesma lógica de idempotência.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Reconectou? Faça revalidação.","Evento duplicado não deve duplicar efeito.","Ordem pode exigir versão/timestamp.","Estado persistente vence evento transitório."],"title":"Como pensar na prática"},{"body":"Um chat recebe mensagens realtime, mas ao reconectar busca mensagens desde o último cursor. Um painel de pagamento recebe evento e depois consulta o pedido atualizado.","type":"example","title":"Exemplo aplicado"},{"body":"Usar WebSocket como único banco de dados torna perda de conexão equivalente a perda de verdade para o cliente.","type":"mistake","title":"Falha que parece pequena"},{"body":"Desenhe a recuperação de um dashboard que ficou offline por 10 minutos e voltou a receber eventos.","type":"guided_practice","title":"Prática orientada"},{"body":"Realtime robusto é combinação de baixa latência com reconciliação. A confiabilidade vem do estado persistente.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Evento não substitui fonte autoritativa.","Reconexão exige catch-up.","Duplicidade e ordem precisam de estratégia.","Idempotência conecta frontend e backend."]}],"lab_type":"checkpoint","position":5,"objective":"Integrar eventos em tempo real sem assumir ordem perfeita nem entrega exatamente uma vez.","xp_reward":150,"difficulty":5,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Assumir que nada mudou.","Reconsultar/reconciliar o estado persistente.","Apagar todos os dados locais.","Desabilitar autenticação."],"feedback":"Correto. Reconciliação cobre eventos perdidos durante a desconexão.","question":"Ao reconectar depois de perder eventos realtime, qual ação aumenta confiabilidade?","feedback_incorrect":"Tempo real melhora latência, mas o estado persistente continua sendo a referência."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":7,"estimated_minutes":34},{"title":"Observabilidade ponta a ponta","content":[{"body":"Um usuário relata “Salvar não funciona”. O frontend mostra timeout, backend registra 500 e banco registra deadlock — mas sem correlação os três parecem incidentes diferentes.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Observabilidade full stack conecta trace/request id, eventos de frontend, logs backend e métricas. A meta é responder: qual fluxo falhou, para quem, onde, desde quando e com qual impacto.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Gere/propague identificador de requisição.","Mensure latência por camada e operação.","Separe erro esperado de exceção inesperada.","Registre contexto técnico sem dados sensíveis."],"title":"Como pensar na prática"},{"body":"Frontend recebe `x-request-id`, inclui esse ID no erro de suporte; backend usa o mesmo ID ao chamar serviço e banco. A investigação localiza a cadeia sem precisar do payload do usuário.","type":"example","title":"Exemplo aplicado"},{"body":"Logar cada clique e cada campo digitado aumenta custo e risco de privacidade sem necessariamente melhorar diagnóstico.","type":"mistake","title":"Falha que parece pequena"},{"body":"Defina três métricas e três logs para o fluxo de checkout, incluindo taxa de sucesso e latência.","type":"guided_practice","title":"Prática orientada"},{"body":"Observabilidade é uma capacidade de produto: ela reduz tempo de falha e permite priorizar o que realmente afeta usuários.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Correlação conecta camadas.","Métricas mostram tendência; logs explicam eventos.","Privacidade limita contexto registrado.","Observe fluxos críticos, não ruído indiscriminado."]}],"lab_type":"checkpoint","position":6,"objective":"Correlacionar experiência do usuário, chamadas de API e banco para diagnosticar falhas reais.","xp_reward":150,"difficulty":5,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Cor favorita do usuário.","Request/correlation ID compartilhado.","Tamanho da tela apenas.","Nome do arquivo CSS."],"feedback":"Correto. Um identificador propagado conecta eventos da mesma operação.","question":"Qual dado ajuda a conectar um erro do frontend ao log correspondente no backend?","feedback_incorrect":"Procure um identificador técnico que atravesse as camadas sem copiar dados sensíveis."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":7,"estimated_minutes":36}]$lessons$::jsonb)
  as x(module_position int,position int,title text,objective text,estimated_minutes int,content jsonb,lesson_type text,lab_type text,lab_config jsonb,xp_reward int,difficulty int)
), c as (select id from nexora.courses where slug='lc-pro-programador-full-stack')
insert into nexora.lessons(module_id,title,objective,estimated_minutes,content,position,status,lesson_type,lab_type,lab_config,xp_reward,difficulty)
select m.id,p.title,p.objective,p.estimated_minutes,p.content,p.position,'draft',p.lesson_type,p.lab_type,p.lab_config,p.xp_reward,p.difficulty
from payload p,c join nexora.modules m on m.course_id=c.id and m.position=p.module_position
on conflict(module_id,position) do update set
 title=excluded.title,objective=excluded.objective,estimated_minutes=excluded.estimated_minutes,content=excluded.content,
 lesson_type=excluded.lesson_type,lab_type=excluded.lab_type,lab_config=excluded.lab_config,xp_reward=excluded.xp_reward,
 difficulty=excluded.difficulty,updated_at=now();

with payload as (
  select * from jsonb_to_recordset($assessments$[{"title":"LC Pro Full Stack — M4 • Checkpoint","pass_score":70,"max_attempts":3,"module_position":4,"randomize_questions":true},{"title":"LC Pro Full Stack — M5 • Checkpoint","pass_score":70,"max_attempts":3,"module_position":5,"randomize_questions":true},{"title":"LC Pro Full Stack — M6 • Checkpoint","pass_score":70,"max_attempts":3,"module_position":6,"randomize_questions":true},{"title":"LC Pro Full Stack — M7 • Checkpoint","pass_score":70,"max_attempts":3,"module_position":7,"randomize_questions":true}]$assessments$::jsonb)
  as x(module_position int,title text,pass_score numeric,max_attempts int,randomize_questions boolean)
), c as (select id from nexora.courses where slug='lc-pro-programador-full-stack')
insert into nexora.assessments(course_id,module_id,title,pass_score,max_attempts,randomize_questions,status)
select c.id,m.id,p.title,p.pass_score,p.max_attempts,p.randomize_questions,'draft'
from payload p,c join nexora.modules m on m.course_id=c.id and m.position=p.module_position
where not exists(
  select 1 from nexora.assessments a where a.course_id=c.id and a.module_id=m.id and a.title=p.title
);

with payload as (
  select * from jsonb_to_recordset($questions$[{"prompt":"Qual dado deve ser usado como fonte principal de identidade numa operação autenticada?","options":[{"id":"c","label":"Campo hidden da interface"},{"id":"d","label":"Nome exibido no perfil"},{"id":"a","label":"userId enviado no JSON"},{"id":"b","label":"Identidade validada da sessão/token no servidor"}],"position":1,"difficulty":2,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":4,"assessment_title":"LC Pro Full Stack — M4 • Checkpoint","feedback_correct":"Correto. A identidade deve vir de credencial validada pelo servidor.","feedback_incorrect":"Dados enviados pelo próprio cliente podem ser manipulados."},{"prompt":"Qual camada deveria decidir se um reembolso ainda está dentro do prazo permitido?","options":[{"id":"b","label":"Serviço/caso de uso"},{"id":"c","label":"Arquivo de rota apenas por ser HTTP"},{"id":"d","label":"Componente React"},{"id":"a","label":"CSS"}],"position":2,"difficulty":2,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":4,"assessment_title":"LC Pro Full Stack — M4 • Checkpoint","feedback_correct":"Correto. Prazo de reembolso é regra de negócio e deve ficar independente do transporte.","feedback_incorrect":"Separe regra de domínio de detalhes do protocolo."},{"prompt":"Qual status representa melhor um conflito de unicidade conhecido, como e-mail já cadastrado?","options":[{"id":"b","label":"204"},{"id":"c","label":"409"},{"id":"d","label":"503"},{"id":"a","label":"201"}],"position":3,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"c"},"module_position":4,"assessment_title":"LC Pro Full Stack — M4 • Checkpoint","feedback_correct":"Correto. 409 comunica conflito com o estado atual do recurso.","feedback_incorrect":"Diferencie entrada inválida de conflito com um registro existente."},{"prompt":"Qual mecanismo ajuda a evitar duas cobranças quando a mesma intenção é reenviada?","options":[{"id":"d","label":"Usar apenas GET para pagamentos."},{"id":"a","label":"Trocar a cor do botão."},{"id":"b","label":"Chave de idempotência persistida no servidor."},{"id":"c","label":"Aumentar timeout indefinidamente."}],"position":4,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":4,"assessment_title":"LC Pro Full Stack — M4 • Checkpoint","feedback_correct":"Correto. A chave permite reconhecer e reutilizar o resultado da mesma intenção.","feedback_incorrect":"A solução precisa funcionar mesmo se a repetição não vier da interface."},{"prompt":"Qual informação NÃO deve ser registrada em logs de produção?","options":[{"id":"d","label":"código estável do erro"},{"id":"a","label":"request_id"},{"id":"b","label":"duration_ms"},{"id":"c","label":"token de autenticação completo"}],"position":5,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"c"},"module_position":4,"assessment_title":"LC Pro Full Stack — M4 • Checkpoint","feedback_correct":"Correto. Credenciais completas não pertencem a logs.","feedback_incorrect":"Log deve ajudar diagnóstico sem criar uma nova fonte de segredos."},{"prompt":"Qual é a melhor defesa quando um webhook informa pagamento aprovado?","options":[{"id":"b","label":"Consultar/validar o evento com o provedor e comparar referência/valor."},{"id":"c","label":"Liberar acesso antes de ler o pedido."},{"id":"d","label":"Desabilitar logs."},{"id":"a","label":"Confiar no JSON recebido sem verificação."}],"position":6,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":4,"assessment_title":"LC Pro Full Stack — M4 • Checkpoint","feedback_correct":"Correto. O servidor deve confirmar o evento e relacioná-lo ao pedido esperado.","feedback_incorrect":"Um endpoint público não deve transformar qualquer payload em autorização financeira."},{"prompt":"Qual combinação produz uma API mais robusta?","options":[{"id":"a","label":"Confiar no cliente + concatenar SQL + sempre 200"},{"id":"b","label":"Autorizar no servidor + erros estruturados + idempotência em efeitos críticos"},{"id":"c","label":"Expor segredos para reduzir latência"},{"id":"d","label":"Gravar request inteira em log"}],"position":7,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":4,"assessment_title":"LC Pro Full Stack — M4 • Checkpoint","feedback_correct":"Correto. Segurança, semântica de erro e idempotência atacam riscos diferentes e complementares.","feedback_incorrect":"Procure controles que continuam válidos mesmo com cliente hostil e rede instável."},{"prompt":"Como modelar muitos usuários participando de muitos projetos com um papel por participação?","options":[{"id":"d","label":"Duplicar dados do usuário em projects."},{"id":"a","label":"Uma coluna projects em users com texto CSV."},{"id":"b","label":"Tabela project_members com user_id, project_id e role."},{"id":"c","label":"Uma tabela diferente para cada usuário."}],"position":1,"difficulty":2,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":5,"assessment_title":"LC Pro Full Stack — M5 • Checkpoint","feedback_correct":"Correto. A tabela de relação representa participação e seus atributos.","feedback_incorrect":"O relacionamento possui dados próprios e precisa de integridade referencial."},{"prompt":"Qual mecanismo impede duas linhas com o mesmo e-mail quando essa unicidade é obrigatória?","options":[{"id":"c","label":"LEFT JOIN"},{"id":"d","label":"VIEW"},{"id":"a","label":"ORDER BY"},{"id":"b","label":"UNIQUE constraint"}],"position":2,"difficulty":2,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":5,"assessment_title":"LC Pro Full Stack — M5 • Checkpoint","feedback_correct":"Correto. A constraint garante a regra independentemente do caminho de escrita.","feedback_incorrect":"A regra deve ser protegida no estado persistente, não só na interface."},{"prompt":"Depois de juntar pedidos com itens, `count(*)` tende a contar o quê?","options":[{"id":"b","label":"As linhas resultantes da junção, frequentemente itens."},{"id":"c","label":"Sempre pedidos distintos."},{"id":"d","label":"Apenas valores não nulos da primeira tabela."},{"id":"a","label":"Sempre clientes."}],"position":3,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":5,"assessment_title":"LC Pro Full Stack — M5 • Checkpoint","feedback_correct":"Correto. A granularidade após o JOIN determina o significado da contagem.","feedback_incorrect":"Antes de agregar, descubra o que cada linha do resultado representa."},{"prompt":"Qual abordagem reduz melhor a corrida ao consumir a última unidade de estoque?","options":[{"id":"a","label":"Ler quantidade no frontend e confiar nela."},{"id":"b","label":"UPDATE condicional que só decrementa se qty > 0."},{"id":"c","label":"Adicionar sleep antes do update."},{"id":"d","label":"Fazer duas leituras iguais."}],"position":4,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":5,"assessment_title":"LC Pro Full Stack — M5 • Checkpoint","feedback_correct":"Correto. A condição é aplicada atomicamente na escrita.","feedback_incorrect":"A decisão precisa ocorrer onde o estado é atualizado, não num snapshot antigo."},{"prompt":"Qual é o melhor primeiro passo antes de adicionar um índice para uma consulta lenta?","options":[{"id":"d","label":"Trocar todos os tipos para text."},{"id":"a","label":"Adicionar índices em todas as colunas."},{"id":"b","label":"Examinar a consulta e seu plano de execução."},{"id":"c","label":"Remover foreign keys."}],"position":5,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":5,"assessment_title":"LC Pro Full Stack — M5 • Checkpoint","feedback_correct":"Correto. O plano ajuda a identificar onde o banco está gastando trabalho.","feedback_incorrect":"Otimize a partir de evidência do caminho executado."},{"prompt":"Qual padrão protege valores externos contra injeção SQL?","options":[{"id":"c","label":"Codificar tudo em base64."},{"id":"d","label":"Usar comentários SQL."},{"id":"a","label":"Concatenar strings e remover aspas."},{"id":"b","label":"Prepared statement/query parametrizada."}],"position":6,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":5,"assessment_title":"LC Pro Full Stack — M5 • Checkpoint","feedback_correct":"Correto. Valores ficam separados da estrutura da consulta.","feedback_incorrect":"A defesa deve vir da interface do driver, não de filtros manuais."},{"prompt":"Qual combinação melhor protege integridade e performance do banco?","options":[{"id":"b","label":"Constraints para invariantes + queries parametrizadas + índices guiados por plano"},{"id":"c","label":"Remover FKs e usar texto para tudo"},{"id":"d","label":"Criar índice em toda coluna"},{"id":"a","label":"Somente validação de frontend"}],"position":7,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":5,"assessment_title":"LC Pro Full Stack — M5 • Checkpoint","feedback_correct":"Correto. Integridade, segurança e performance exigem mecanismos distintos.","feedback_incorrect":"Escolha a opção que usa o banco como parte ativa da arquitetura."},{"prompt":"Após autenticar um usuário, o que ainda precisa ser verificado antes de editar um recurso?","options":[{"id":"a","label":"Somente se a tela tem botão Editar."},{"id":"b","label":"Se a identidade possui autorização para aquele recurso e ação."},{"id":"c","label":"A resolução da tela."},{"id":"d","label":"A linguagem do navegador."}],"position":1,"difficulty":2,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":6,"assessment_title":"LC Pro Full Stack — M6 • Checkpoint","feedback_correct":"Correto. Autenticação e autorização resolvem perguntas diferentes.","feedback_incorrect":"Estar logado não define automaticamente quais recursos podem ser modificados."},{"prompt":"Como uma senha deve ser armazenada no banco?","options":[{"id":"d","label":"Dentro do log de autenticação."},{"id":"a","label":"Texto puro para facilitar suporte."},{"id":"b","label":"Hash produzido por função apropriada para senhas."},{"id":"c","label":"Base64 reversível."}],"position":2,"difficulty":2,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":6,"assessment_title":"LC Pro Full Stack — M6 • Checkpoint","feedback_correct":"Correto. O sistema verifica o hash sem precisar recuperar a senha original.","feedback_incorrect":"Procure um mecanismo resistente a brute force e não reversível."},{"prompt":"Qual policy representa melhor acesso do próprio usuário a linhas com `user_id`?","options":[{"id":"c","label":"USING (status IS NOT NULL)"},{"id":"d","label":"Sem RLS"},{"id":"a","label":"USING (true)"},{"id":"b","label":"USING (auth.uid() = user_id)"}],"position":3,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":6,"assessment_title":"LC Pro Full Stack — M6 • Checkpoint","feedback_correct":"Correto. A policy vincula a linha à identidade autenticada.","feedback_incorrect":"Autenticação sozinha não limita quais linhas uma conta pode ler."},{"prompt":"Qual propriedade é preferível para inserir comentário não confiável como texto no DOM?","options":[{"id":"c","label":"textContent"},{"id":"d","label":"document.write"},{"id":"a","label":"innerHTML"},{"id":"b","label":"outerHTML"}],"position":4,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"c"},"module_position":6,"assessment_title":"LC Pro Full Stack — M6 • Checkpoint","feedback_correct":"Correto. `textContent` não interpreta a entrada como marcação HTML.","feedback_incorrect":"A defesa deve impedir que texto fornecido pelo usuário vire código/marcação executável."},{"prompt":"O que deve acontecer quando um segredo de backend foi commitado publicamente?","options":[{"id":"a","label":"Só apagar o arquivo no próximo commit."},{"id":"b","label":"Rotacionar/revogar a credencial e remover o uso indevido."},{"id":"c","label":"Renomear a variável."},{"id":"d","label":"Esconder o repositório e manter a mesma chave."}],"position":5,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":6,"assessment_title":"LC Pro Full Stack — M6 • Checkpoint","feedback_correct":"Correto. Uma credencial exposta deve ser considerada comprometida.","feedback_incorrect":"Remover texto do branch atual não invalida cópias já obtidas."},{"prompt":"Qual risco existe em uma função `SECURITY DEFINER` exposta sem checagem interna de autorização?","options":[{"id":"d","label":"Somente altera CSS."},{"id":"a","label":"Nenhum, porque RLS sempre se aplica."},{"id":"b","label":"Ela pode executar com privilégios elevados e contornar RLS."},{"id":"c","label":"Apenas deixa a query mais lenta."}],"position":6,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":6,"assessment_title":"LC Pro Full Stack — M6 • Checkpoint","feedback_correct":"Correto. SECURITY DEFINER executa com privilégios do dono e exige desenho cuidadoso.","feedback_incorrect":"Função privilegiada pode transformar EXECUTE em uma rota de escalada."},{"prompt":"Qual afirmação sobre autorização é correta?","options":[{"id":"c","label":"CORS substitui autorização."},{"id":"d","label":"Hash de senha define papel do usuário."},{"id":"a","label":"Usuário autenticado pode ler qualquer linha."},{"id":"b","label":"RLS/ownership deve vincular recurso à identidade ou papel autorizado."}],"position":7,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":6,"assessment_title":"LC Pro Full Stack — M6 • Checkpoint","feedback_correct":"Correto. Autorização precisa limitar recurso e ação, não apenas exigir login.","feedback_incorrect":"Identidade autenticada é o começo, não o fim do controle."},{"prompt":"Por que TypeScript no frontend não substitui validação do JSON recebido da API?","options":[{"id":"b","label":"Porque tipos são apagados em runtime e a rede ainda pode trazer dados diferentes."},{"id":"c","label":"Porque JSON não tem strings."},{"id":"d","label":"Porque HTTP só envia bytes tipados."},{"id":"a","label":"Porque TypeScript não funciona com React."}],"position":1,"difficulty":2,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":7,"assessment_title":"LC Pro Full Stack — M7 • Checkpoint","feedback_correct":"Correto. O dado externo precisa ser validado em runtime.","feedback_incorrect":"O compilador não controla o que um servidor ou cache realmente envia."},{"prompt":"O que um 403 normalmente comunica?","options":[{"id":"a","label":"O servidor não existe."},{"id":"b","label":"A identidade é conhecida, mas a ação não é permitida."},{"id":"c","label":"O JSON está sempre inválido."},{"id":"d","label":"A sessão foi necessariamente apagada."}],"position":2,"difficulty":2,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":7,"assessment_title":"LC Pro Full Stack — M7 • Checkpoint","feedback_correct":"Correto. 403 representa falta de autorização para a ação/recurso.","feedback_incorrect":"Não confunda ausência de credencial com permissão insuficiente."},{"prompt":"Após uma mutação que altera o status de uma tarefa, o que deve acontecer com leituras derivadas desse status?","options":[{"id":"d","label":"Ter seus erros ignorados."},{"id":"a","label":"Nada, porque cache nunca expira."},{"id":"b","label":"Ser atualizadas ou invalidadas conforme dependência."},{"id":"c","label":"Ser convertidas em localStorage permanente."}],"position":3,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":7,"assessment_title":"LC Pro Full Stack — M7 • Checkpoint","feedback_correct":"Correto. Leituras dependentes precisam refletir a mudança ou serem recarregadas.","feedback_incorrect":"Cache sem invalidação produz estados contraditórios."},{"prompt":"Qual abordagem é adequada para download temporário de arquivo privado?","options":[{"id":"c","label":"Nome de arquivo secreto como única proteção."},{"id":"d","label":"Enviar service role ao navegador."},{"id":"a","label":"Bucket público permanente."},{"id":"b","label":"URL assinada com expiração após autorização."}],"position":4,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":7,"assessment_title":"LC Pro Full Stack — M7 • Checkpoint","feedback_correct":"Correto. A URL assinada concede acesso limitado após checagem de autorização.","feedback_incorrect":"Segredo ou privilégio do servidor não deve ser entregue ao cliente."},{"prompt":"Ao reconectar depois de perder eventos realtime, qual ação aumenta confiabilidade?","options":[{"id":"b","label":"Reconsultar/reconciliar o estado persistente."},{"id":"c","label":"Apagar todos os dados locais."},{"id":"d","label":"Desabilitar autenticação."},{"id":"a","label":"Assumir que nada mudou."}],"position":5,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":7,"assessment_title":"LC Pro Full Stack — M7 • Checkpoint","feedback_correct":"Correto. Reconciliação cobre eventos perdidos durante a desconexão.","feedback_incorrect":"Tempo real melhora latência, mas o estado persistente continua sendo a referência."},{"prompt":"Qual dado ajuda a conectar um erro do frontend ao log correspondente no backend?","options":[{"id":"a","label":"Cor favorita do usuário."},{"id":"b","label":"Request/correlation ID compartilhado."},{"id":"c","label":"Tamanho da tela apenas."},{"id":"d","label":"Nome do arquivo CSS."}],"position":6,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":7,"assessment_title":"LC Pro Full Stack — M7 • Checkpoint","feedback_correct":"Correto. Um identificador propagado conecta eventos da mesma operação.","feedback_incorrect":"Procure um identificador técnico que atravesse as camadas sem copiar dados sensíveis."},{"prompt":"Qual princípio torna uma aplicação distribuída mais resiliente?","options":[{"id":"d","label":"Duplicar estado sem fonte de verdade."},{"id":"a","label":"Assumir que requests e eventos chegam uma única vez e em ordem."},{"id":"b","label":"Projetar reconciliação, idempotência e estados de erro explícitos."},{"id":"c","label":"Ocultar todo erro do usuário e dos logs."}],"position":7,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":7,"assessment_title":"LC Pro Full Stack — M7 • Checkpoint","feedback_correct":"Correto. Rede e eventos falham; o sistema precisa recuperar consistência.","feedback_incorrect":"Procure uma estratégia que continue funcionando sob repetição, perda e atraso."}]$questions$::jsonb)
  as x(module_position int,assessment_title text,position int,prompt text,question_type text,options jsonb,correct_answer jsonb,feedback_correct text,feedback_incorrect text,difficulty int)
), c as (select id from nexora.courses where slug='lc-pro-programador-full-stack')
insert into nexora.questions(assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position)
select a.id,p.prompt,p.question_type,p.options,p.correct_answer,p.feedback_correct,p.feedback_incorrect,p.difficulty,p.position
from payload p,c
join nexora.modules m on m.course_id=c.id and m.position=p.module_position
join nexora.assessments a on a.course_id=c.id and a.module_id=m.id and a.title=p.assessment_title
where not exists(select 1 from nexora.questions q where q.assessment_id=a.id and q.position=p.position);
